const IdentityDocumentScannerModal = ({ onClose, onComplete, email }: { onClose: () => void, onComplete: () => void, email: string }) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const [scanState, setScanState] = useState<'idle' | 'scanning' | 'analyzing' | 'success'>('idle');

    useEffect(() => {
        let stream: MediaStream | null = null;
        const startCamera = async () => {
            try {
                stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
                if (videoRef.current) {
                    videoRef.current.srcObject = stream;
                }
            } catch (err) {
                console.warn("Camera error:", err);
            }
        };
        startCamera();
        return () => {
            if (stream) stream.getTracks().forEach(t => t.stop());
        };
    }, []);

    const captureAndScan = () => {
        setScanState('scanning');
        setTimeout(() => {
            setScanState('analyzing');
            setTimeout(() => {
                setScanState('success');
                setTimeout(() => {
                    onComplete();
                }, 1500);
            }, 2000);
        }, 1500);
    };

    return (
        <div className="fixed inset-0 z-[200] bg-slate-100  flex flex-col items-center justify-center p-4 animate-in fade-in duration-300">
            <div className="w-full max-w-lg bg-slate-50 border border-black/5 rounded-[2.5rem] overflow-hidden relative shadow-2xl animate-in zoom-in-95 duration-500 dark:bg-slate-900">
                <button onClick={onClose} className="absolute top-6 right-6 z-10 text-white/50 hover:text-white transition-colors">
                    <XCircleIcon className="w-8 h-8" />
                </button>
                <div className="p-8 text-center bg-slate-100">
                    <h3 className="text-xl font-black text-white uppercase tracking-widest mb-2">Automated KYC Scanner</h3>
                    <p className="text-xs text-[#0F172A] font-mono">Present ID Card or Passport to the camera for entity: <span className="text-primary">{email}</span></p>
                </div>
                <div className="relative aspect-video bg-slate-100 flex items-center justify-center overflow-hidden">
                    <video ref={videoRef} autoPlay playsInline muted className="absolute inset-0 w-full h-full object-cover opacity-60" />
                    <div className="absolute inset-6 border-2 border-primary/50 border-dashed rounded-xl pointer-events-none"></div>
                    
                    {scanState === 'scanning' && (
                        <div className="absolute inset-0 flex items-center justify-center bg-primary/20 ">
                            <div className="w-full h-2 bg-primary/80 absolute top-0 animate-scan-vertical shadow-[0_0_30px_rgba(14,197,242,1)]" />
                            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-white"></div>
                        </div>
                    )}
                    {scanState === 'analyzing' && (
                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-100 ">
                            <CodeBracketIcon className="w-12 h-12 text-primary animate-pulse mb-4" />
                            <div className="text-xs font-mono text-primary uppercase tracking-widest">Extracting Biographic OCR Data...</div>
                        </div>
                    )}
                    {scanState === 'success' && (
                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-emerald-900 ">
                            <CheckCircleIcon className="w-16 h-16 text-emerald-400 mb-4" />
                            <div className="text-sm font-black text-white uppercase tracking-widest">Identity Verified</div>
                            <div className="text-[10px] font-mono text-emerald-300 mt-2">MRZ / Federal Match Confirmed</div>
                        </div>
                    )}
                </div>
                <div className="p-6 bg-slate-50 border-t border-black/5 dark:bg-slate-900">
                    <button 
                        onClick={captureAndScan} 
                        disabled={scanState !== 'idle'}
                        className="w-full py-4 bg-primary text-[#0F172A] font-black uppercase tracking-widest text-[10px] rounded-xl hover:bg-emerald-400 transition-colors disabled:opacity-70 flex items-center justify-center gap-3"
                    >
                        {scanState === 'idle' ? <CameraIcon className="w-5 h-5" /> : null}
                        {scanState === 'idle' ? 'Capture & Analyze Document' : 'Processing Neural Verification...'}
                    </button>
                </div>
            </div>
        </div>
    );
};

interface TelemetryPoint {
    time: string;
    hourLabel: string;
    ledgerLatency: number;
    clearanceLatency: number;
    ledgerSuccess: number;
    clearanceSuccess: number;
}

export const D3HealthLineChart: React.FC<{ metrics: any }> = ({ metrics }) => {
    const svgRef = useRef<SVGSVGElement | null>(null);
    const [viewMetric, setViewMetric] = useState<'latency' | 'success' | 'both'>('latency');

    const telemetryData = useMemo<TelemetryPoint[]>(() => {
        const points: TelemetryPoint[] = [];
        const now = new Date();
        for (let i = 23; i >= 0; i--) {
            const time = new Date(now.getTime() - i * 60 * 60 * 1000);
            const hourLabel = `${time.getHours().toString().padStart(2, '0')}:00`;
            const noise = (Math.sin(i * 0.7) + 1) * 3;
            const ledgerLatency = Math.round(Math.max(8, (metrics?.ledger?.latency || 14) + (i % 6 === 0 ? 9 : -2) + noise));
            const clearanceLatency = Math.round(Math.max(12, (metrics?.clearance?.latency || 22) + (i % 4 === 0 ? 11 : -3) + noise * 1.3));
            
            const ledgerSuccess = Number((100 - (ledgerLatency > 35 ? 0.25 : 0.02)).toFixed(2));
            const clearanceSuccess = Number((100 - (clearanceLatency > 40 ? 0.45 : 0.05)).toFixed(2));

            points.push({
                time: time.toISOString(),
                hourLabel,
                ledgerLatency,
                clearanceLatency,
                ledgerSuccess,
                clearanceSuccess
            });
        }
        return points;
    }, [metrics]);

    useEffect(() => {
        if (!svgRef.current || telemetryData.length === 0) return;

        const svg = d3.select(svgRef.current);
        svg.selectAll('*').remove();

        const containerWidth = svgRef.current.parentElement?.clientWidth || 600;
        const width = Math.max(300, containerWidth);
        const height = 180;
        const margin = { top: 20, right: 35, bottom: 30, left: 35 };

        svg.attr('width', width).attr('height', height).attr('viewBox', `0 0 ${width} ${height}`);

        const innerWidth = width - margin.left - margin.right;
        const innerHeight = height - margin.top - margin.bottom;

        const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);

        const xScale = d3.scalePoint()
            .domain(telemetryData.map(d => d.hourLabel))
            .range([0, innerWidth])
            .padding(0.1);

        const maxLatency = d3.max(telemetryData, d => Math.max(d.ledgerLatency, d.clearanceLatency)) || 50;
        const yScaleLatency = d3.scaleLinear()
            .domain([0, maxLatency * 1.25])
            .range([innerHeight, 0]);

        const yScaleSuccess = d3.scaleLinear()
            .domain([98, 100.1])
            .range([innerHeight, 0]);

        const yTicks = viewMetric === 'success' ? yScaleSuccess.ticks(4) : yScaleLatency.ticks(4);
        g.selectAll('.gridline')
            .data(yTicks)
            .enter()
            .append('line')
            .attr('x1', 0)
            .attr('x2', innerWidth)
            .attr('y1', d => viewMetric === 'success' ? yScaleSuccess(d) : yScaleLatency(d))
            .attr('y2', d => viewMetric === 'success' ? yScaleSuccess(d) : yScaleLatency(d))
            .attr('stroke', '#ffffff')
            .attr('stroke-opacity', 0.06)
            .attr('stroke-dasharray', '3,3');

        const ledgerLine = d3.line<TelemetryPoint>()
            .x(d => xScale(d.hourLabel) || 0)
            .y(d => viewMetric === 'success' ? yScaleSuccess(d.ledgerSuccess) : yScaleLatency(d.ledgerLatency))
            .curve(d3.curveMonotoneX);

        const clearanceLine = d3.line<TelemetryPoint>()
            .x(d => xScale(d.hourLabel) || 0)
            .y(d => viewMetric === 'success' ? yScaleSuccess(d.clearanceSuccess) : yScaleLatency(d.clearanceLatency))
            .curve(d3.curveMonotoneX);

        const ledgerArea = d3.area<TelemetryPoint>()
            .x(d => xScale(d.hourLabel) || 0)
            .y0(innerHeight)
            .y1(d => viewMetric === 'success' ? yScaleSuccess(d.ledgerSuccess) : yScaleLatency(d.ledgerLatency))
            .curve(d3.curveMonotoneX);

        const defs = svg.append('defs');
        const gradLedger = defs.append('linearGradient').attr('id', 'd3GradLedger').attr('x1', '0').attr('y1', '0').attr('x2', '0').attr('y2', '1');
        gradLedger.append('stop').attr('offset', '0%').attr('stop-color', '#06b6d4').attr('stop-opacity', 0.25);
        gradLedger.append('stop').attr('offset', '100%').attr('stop-color', '#06b6d4').attr('stop-opacity', 0.0);

        g.append('path')
            .datum(telemetryData)
            .attr('fill', 'url(#d3GradLedger)')
            .attr('d', ledgerArea);

        g.append('path')
            .datum(telemetryData)
            .attr('fill', 'none')
            .attr('stroke', '#06b6d4')
            .attr('stroke-width', 2.5)
            .attr('d', ledgerLine);

        g.append('path')
            .datum(telemetryData)
            .attr('fill', 'none')
            .attr('stroke', '#10b981')
            .attr('stroke-width', 2.5)
            .attr('stroke-dasharray', viewMetric === 'both' ? '4,4' : 'none')
            .attr('d', clearanceLine);

        g.selectAll('.dot-ledger')
            .data(telemetryData)
            .enter()
            .append('circle')
            .attr('cx', d => xScale(d.hourLabel) || 0)
            .attr('cy', d => viewMetric === 'success' ? yScaleSuccess(d.ledgerSuccess) : yScaleLatency(d.ledgerLatency))
            .attr('r', 3)
            .attr('fill', '#06b6d4')
            .attr('stroke', '#0f172a')
            .attr('stroke-width', 1.5);

        g.selectAll('.dot-clearance')
            .data(telemetryData)
            .enter()
            .append('circle')
            .attr('cx', d => xScale(d.hourLabel) || 0)
            .attr('cy', d => viewMetric === 'success' ? yScaleSuccess(d.clearanceSuccess) : yScaleLatency(d.clearanceLatency))
            .attr('r', 3)
            .attr('fill', '#10b981')
            .attr('stroke', '#0f172a')
            .attr('stroke-width', 1.5);

        const xAxis = d3.axisBottom(xScale)
            .tickValues(xScale.domain().filter((_, idx) => idx % 4 === 0 || idx === telemetryData.length - 1));
        g.append('g')
            .attr('transform', `translate(0,${innerHeight})`)
            .call(xAxis)
            .selectAll('text')
            .attr('fill', '#64748b')
            .attr('font-size', '9px')
            .attr('font-family', 'monospace');

        const yAxis = d3.axisLeft(viewMetric === 'success' ? yScaleSuccess : yScaleLatency).ticks(3);
        g.append('g')
            .call(yAxis)
            .selectAll('text')
            .attr('fill', '#64748b')
            .attr('font-size', '9px')
            .attr('font-family', 'monospace');

        g.selectAll('.domain, .tick line').attr('stroke', '#ffffff15');

    }, [telemetryData, viewMetric]);

    return (
        <div className="mt-4 bg-slate-100 border border-black/5 rounded-2xl p-4">
            <div className="flex flex-wrap items-center justify-between gap-3 mb-2">
                <div className="flex items-center gap-3 font-mono text-[10px]">
                    <span className="flex items-center gap-1.5 text-cyan-400 font-bold">
                        <span className="w-2.5 h-2.5 rounded-full bg-cyan-400 inline-block animate-pulse"></span>
                        Ledger Service
                    </span>
                    <span className="flex items-center gap-1.5 text-emerald-400 font-bold">
                        <span className="w-2.5 h-2.5 rounded-full bg-emerald-400 inline-block animate-pulse"></span>
                        Clearance Service
                    </span>
                </div>
                <div className="flex items-center gap-1 bg-slate-100 p-1 rounded-xl border border-black/5">
                    <button
                        onClick={() => setViewMetric('latency')}
                        className={`px-2.5 py-1 rounded-lg text-[9px] font-mono font-black uppercase transition-all ${viewMetric === 'latency' ? 'bg-cyan-500 text-slate-950' : 'text-[#0F172A] hover:text-white'}`}
                    >
                        Latency (ms)
                    </button>
                    <button
                        onClick={() => setViewMetric('success')}
                        className={`px-2.5 py-1 rounded-lg text-[9px] font-mono font-black uppercase transition-all ${viewMetric === 'success' ? 'bg-emerald-500 text-slate-950' : 'text-[#0F172A] hover:text-white'}`}
                    >
                        Success %
                    </button>
                </div>
            </div>
            <div className="w-full overflow-hidden">
                <svg ref={svgRef} className="w-full h-[180px]"></svg>
            </div>
        </div>
    );
};

