    const [crediLinkError, setCrediLinkError] = useState('');
    const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
    const [isGeneratingComplianceReport, setIsGeneratingComplianceReport] = useState(false);
    const [pdfData, setPdfData] = useState<{ transaction: Transaction; account: Account } | null>(null);
    const [selectedUserDetails, setSelectedUserDetails] = useState<{ isOpen: boolean, user: UserRecord } | null>(null);
    
    // Reconciliation and loading states
    const [isEntitiesLoading, setIsEntitiesLoading] = useState(false);
    const [entitiesLastSynced, setEntitiesLastSynced] = useState<Date>(new Date());

    // Interactive Liquidity Flow & Overview States
    const [liquidityTimeframe, setLiquidityTimeframe] = useState<'24H' | '7D' | '30D'>('24H');
