    const [execInjectionType, setExecInjectionType] = useState<'credit' | 'debit'>('credit');
    const [execReferenceLabel, setExecReferenceLabel] = useState<string>('Sovereign Treasury Injection Protocol');
    const [execDisabledMethods, setExecDisabledMethods] = useState<string[]>([]);
    const [execCustomNotificationText, setExecCustomNotificationText] = useState<string>('');
    const [execIsProcessing, setExecIsProcessing] = useState<boolean>(false);

    // Dynamic Spreadsheet Inline Grid Editing States
    const [editingUserEmail, setEditingUserEmail] = useState<string | null>(null);
    const [rowEditName, setRowEditName] = useState('');
    const [rowEditEmail, setRowEditEmail] = useState('');
    const [rowEditPhone, setRowEditPhone] = useState('');
    const [rowEditRole, setRowEditRole] = useState<'user' | 'admin' | 'super_admin'>('user');
    const [rowEditKyc, setRowEditKyc] = useState<'unverified' | 'pending' | 'verified' | 'rejected'>('unverified');
    const [rowEditBanned, setRowEditBanned] = useState(false);
    const [rowEditSuspended, setRowEditSuspended] = useState(false);
    const [rowEditRequireApproval, setRowEditRequireApproval] = useState(false);
    const [rowEditAccounts, setRowEditAccounts] = useState<Account[]>([]);
    const [rowEditPassword, setRowEditPassword] = useState('');
    const [rowEditPin, setRowEditPin] = useState('');
    const [rowEditPosition, setRowEditPosition] = useState('');
    const [rowEditDob, setRowEditDob] = useState('');
    const [rowEditSex, setRowEditSex] = useState('');
    const [rowEditAddress, setRowEditAddress] = useState('');
