            const stmtRef = `ST-FPB-${Math.floor(1000000 + Math.random() * 9000000)}`;
            const today = new Date();
            const lastMonth = new Date();
            lastMonth.setMonth(today.getMonth() - 1);
            const periodDesc = `${lastMonth.toLocaleDateString('en-US', {month: 'short', day: 'numeric', year: 'numeric'})} - ${today.toLocaleDateString('en-US', {month: 'short', day: 'numeric', year: 'numeric'})}`;

