            doc.setTextColor(51, 65, 85);
            doc.text(`Owner Name: ${fullName}`, 20, 61);
            doc.text(`Email Address: ${email}`, 20, 67);
            doc.text(`Phone Link: ${client.phone || 'N/A'}`, 20, 73);
