                doc.text(`- Document Type: ${client.governmentIdType || 'Passport/ID Scan'}\n- Document Reference Number: ${client.governmentIdNumber || 'N/A'}\n- Expiry validation standard: SECURE SYSTEM CLEARANCE\n- Encrypted Hash: ${stmtRef.slice(4)}`, 25, 187);
