            doc.setTextColor(100, 116, 139);
            doc.text('I hereby certify and declare under penalties of perjury that all tax identification numbers, address matrices, and scanned government identification records provided herein are authentic, unexpired, and legitimately associated with this member enclave.', 22, 227, { maxWidth: 165 });

            // Signature lines
