    useEffect(() => {
        const handleAdminNavigation = (e: Event) => {
            const customEvent = e as CustomEvent;
            const targetTab = customEvent.detail?.tab;
            if (targetTab) {
                console.log(`[REALTIME NAVIGATOR] Redirecting Admin user to tab: ${targetTab}`);
                setActiveTab(targetTab);
            }
        };
        window.addEventListener('admin:navigate', handleAdminNavigation);
        return () => window.removeEventListener('admin:navigate', handleAdminNavigation);
    }, []);

    useEffect(() => {
        const stored = localStorage.getItem('prb_reported_incidents');
        if (stored) {
            try {
                setReportedIncidents(JSON.parse(stored));
            } catch (err) {
                console.error(err);
            }
        }
    }, [activeTab]);

    const handleUpdateTransactionStatus = async (txId: string, updates: Partial<Transaction>) => {
        try {
            const tx = allTransactions.find(t => t.id === txId);
            if (!tx) return;
            
            // Instantly update local state for real-time visual feedback
            setAllTransactions(prev => prev.map(t => t.id === txId ? { ...t, ...updates } : t));
            
            // Check for status changes to apply balance adjustments
            if (updates.status && updates.status !== tx.status) {
                if (!updates.statusTimestamps) {
                    updates.statusTimestamps = { ...tx.statusTimestamps } as any;
                }
                (updates.statusTimestamps as any)[updates.status] = new Date();

                const ownerEmail = await db.getEmailByAccountId(tx.accountId);
                if (ownerEmail) {
                    const userAccounts = await db.getAccounts(ownerEmail);
                    const targetAccount = userAccounts.find(a => a.id === tx.accountId);
                    
                    if (targetAccount) {
                        if (updates.status === TransactionStatus.COMPLETED && tx.status !== TransactionStatus.COMPLETED) {
                            // If credit transaction is approved/completed, credit the account
                            if (tx.type === 'credit') {
                                const creditAmt = tx.receiveAmount || tx.sendAmount || 0;
                                const finalBalance = await db.atomicCreditAndNotify(
                                    ownerEmail,
                                    tx.accountId,
                                    creditAmt,
                                    tx,
                                    userProfile.email,
                                    'Credit Issuance (Approval)',
                                    `Credited ${ownerEmail} account ${tx.accountId} with $${creditAmt} USD because Transaction ${txId} was approved.`
                                );

                                // Forced Push Socket Emission to ensure zero-latency UI reflection for connected clients
                                socket.emit('admin:force_accounts_update', {
                                    email: ownerEmail,
                                    accountId: tx.accountId,
                                    newBalance: finalBalance
                                });
                            }
                        } else if (updates.status === TransactionStatus.FAILED && tx.status !== TransactionStatus.FAILED && tx.status !== TransactionStatus.COMPLETED) {
                            // If a debit transaction is rejected/failed, refund the account (sendAmount + fees)
                            if (tx.type === 'debit') {
                                const refundAmt = tx.sendAmount + (tx.fee || 0) + (tx.complianceFee || 0);
                                const newBalance = parseFloat((targetAccount.balance + refundAmt).toFixed(2));
                                await db.updateAccountBalance(ownerEmail, tx.accountId, newBalance);
                                await db.logAuditAction(userProfile.email, `Auto-Refunded Account on Clearance Rejection`, `Refunded ${ownerEmail} account ${tx.accountId} with ${refundAmt} because Transaction ${txId} was rejected`);
                            }
                        }
                    }
                }

                // --- EMIT LIVE REAL-TIME SOCKET EVENTS ---
                const targetEmail = ownerEmail || tx.accountId;
                socket.emit('admin:payment_status_changed', {
                    email: targetEmail,
                    txId,
                    status: updates.status,
                    message: updates.status === TransactionStatus.COMPLETED ? 'Sovereign Release Successful' : 'Compliance hold update'
});

                socket.emit('user:new_notification', {
                    email: targetEmail,
                    type: 'TRANSACTION',
                    title: `Transfer Status: ${updates.status}`,
                    message: `Institutional Transfer ${txId} of $${Number(tx.sendAmount || tx.receiveAmount || 0).toLocaleString()} has transitioned to ${updates.status}.`
});

                // --- TRIGGER AUTOMATIC EMAIL DISPATCH ---
                if (targetEmail) {
                        let statusColor = '#3b82f6';
                        if (updates.status === TransactionStatus.COMPLETED) {
                            statusColor = '#10b981';
                        } else if (updates.status === TransactionStatus.FAILED) {
                            statusColor = '#ef4444';
                        } else if (updates.status === TransactionStatus.PAUSED_ON_HOLD) {
                            statusColor = '#f59e0b';
                        }

                        const emailSubject = `Institutional Status Update: Transfer ${txId} is ${updates.status}`;
                        const titleText = `TRANSFER ${updates.status?.toUpperCase()}`;

                        const formattedAmt = Number(tx.sendAmount || tx.receiveAmount || 0).toLocaleString('en-US', { minimumFractionDigits: 2 });
                        const cur = tx.baseCurrency || tx.receiveCurrency || 'USD';

                        const bodyHtml = generateBankingEmailTemplate(
                            titleText,
                            `<p style="font-size:15px;color:#cbd5e1;">Dear Sovereign Client,</p>
                             <p style="font-size:14px;color:#cbd5e1;">This is an official confirmation that your transaction <strong>${txId}</strong> has been updated to <strong style="color:${statusColor};">${updates.status}</strong> by the clearing system administration.</p>
                             
                             <div style="background-color:#1e293b;border:1px solid #334155;padding:18px;border-radius:12px;margin:24px 0;">
                                 <table style="width:100%;font-size:13px;color:#94a3b8;border-collapse:collapse;">
                                     <tr>
                                         <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Transaction Ref:</td>
                                         <td style="padding:6px 0;text-align:right;font-family:monospace;">${txId}</td>
                                     </tr>
                                     <tr>
                                         <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Transfer Amount:</td>
                                         <td style="padding:6px 0;text-align:right;color:#ffffff;font-weight:bold;font-size:15px;">$${formattedAmt} ${cur}</td>
                                     </tr>
                                     ${tx.fee > 0 ? `<tr>
                                         <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Calculated Service Fee:</td>
                                         <td style="padding:6px 0;text-align:right;">$${Number(tx.fee).toLocaleString('en-US', { minimumFractionDigits: 2 })} ${cur}</td>
                                     </tr>` : ''}
                                     <tr>
                                         <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Description:</td>
                                         <td style="padding:6px 0;text-align:right;">${tx.description || 'Verified Interbank Pool'}</td>
                                     </tr>
                                     <tr>
                                         <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Audit Status:</td>
                                         <td style="padding:6px 0;text-align:right;color:${statusColor};font-weight:bold;">${updates.status}</td>
                                     </tr>
                                 </table>
                             </div>
                             
                             <p style="font-size:13px;color:#94a3b8;line-height:1.6;">
                                 Our clearing system is designed for real-time asset transit and legal alignment. If you did not initiate this transaction or believe there has been an error, please lock your credential set immediately.
                             </p>
                             <p style="font-size:12px;color:#64748b;margin-top:24px;">First Pacific Banking Enclave, Operational Systems Support Node</p>`
                        );

                        sendEmail(
                            targetEmail,
                            emailSubject,
                            bodyHtml
                        ).catch(err => console.error('[EMAIL] Failed to send status update email from clearance:', err));
                }
            }

            const updatedTx = { ...tx, ...updates };
            await db.saveTransaction(updatedTx);
            await db.logAuditAction(userProfile.email, `SuperAdmin Updated Clearance Status`, `Transaction ${txId} clearance status/details updated to ${updates.status}`);

            // --- AUTO-SETTLE PEER P2P TRANSACTIONS ---
            if (updates.status === TransactionStatus.COMPLETED && tx.type === 'debit') {
                const pendingIncomingTx = allTransactions.find(t => 
                    t.type === 'credit' && 
                    t.id.startsWith('P2P-INCOMING-') &&
                    t.status !== TransactionStatus.COMPLETED &&
                    (t.sendAmount === tx.sendAmount || t.receiveAmount === tx.sendAmount) &&
                    (t.accountId === tx.recipient?.email || t.accountId === tx.recipient?.userId || t.recipient?.fullName === tx.recipient?.fullName)
                );
                if (pendingIncomingTx) {
                    console.log("[Clearance] Auto-approving corresponding peer incoming credit transaction:", pendingIncomingTx.id);
                    await handleUpdateTransactionStatus(pendingIncomingTx.id, { status: TransactionStatus.COMPLETED });
                }
            } else if (updates.status === TransactionStatus.COMPLETED && tx.type === 'credit' && tx.id.startsWith('P2P-INCOMING-')) {
                const pendingDebitTx = allTransactions.find(t => 
                    t.type === 'debit' && 
                    t.status !== TransactionStatus.COMPLETED &&
                    (t.sendAmount === tx.sendAmount || t.receiveAmount === tx.sendAmount) &&
                    (t.recipient?.email === tx.accountId || t.recipient?.userId === tx.accountId)
                );
                if (pendingDebitTx) {
                    console.log("[Clearance] Auto-approving corresponding peer outgoing debit transaction:", pendingDebitTx.id);
                    await handleUpdateTransactionStatus(pendingDebitTx.id, { status: TransactionStatus.COMPLETED });
                }
            }

            const updatedTxs = await db.getAllTransactions();
            setAllTransactions(updatedTxs);
            await fetchStats();
        } catch (error) {
            console.error('Failed to update transaction:', error);
            addAdminToast('error', 'System Alert', 'Failed to update transaction status.');
        }
    };

    const handleDeleteClearanceTransaction = async (txId: string) => {
        try {
            setAllTransactions(prev => prev.filter(t => t.id !== txId));
            await db.deleteTransaction(txId);
            await db.logAuditAction(userProfile.email, 'SuperAdmin Delete Clearance Transaction', `Deleted transaction ${txId}`);
            await fetchStats();
        } catch (error) {
            console.error('Failed to delete clearance transaction:', error);
        }
    };

    const handleDeleteClearanceTransactions = async (txIds: string[]) => {
        try {
            const idSet = new Set(txIds);
            setAllTransactions(prev => prev.filter(t => !idSet.has(t.id)));
            await db.deleteTransactions(txIds);
            await db.logAuditAction(userProfile.email, 'SuperAdmin Bulk Delete Clearance Transactions', `Deleted ${txIds.length} transactions`);
            await fetchStats();
        } catch (error) {
            console.error('Failed to bulk delete clearance transactions:', error);
        }
    };

    const handleResolveIncident = (incidentId: string) => {
        const updated = reportedIncidents.map(inc => {
            if (inc.id === incidentId) {
                return { ...inc, status: 'resolved', resolvedAt: new Date().toISOString() };
            }
            return inc;
});
        setReportedIncidents(updated);
        localStorage.setItem('prb_reported_incidents', JSON.stringify(updated));
        addAdminToast('info', 'System Notification', 'SuperAdmin Action: Security Incident Reference ' + incidentId + ' marked as Investigated and RESOLVED.');
    };

    const toggleExpandKyc = (email: string) => {
        const target = email.toLowerCase().trim();
        setExpandedKycEmails(prev => 
            prev.includes(target) ? prev.filter(e => e !== target) : [...prev, target]
        );
        Haptics.tap();
    };

    const handleUploadCustomKycDocument = async (userEmail: string, event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (e) => {
            const base64Url = e.target?.result as string;
            if (!base64Url) return;

            const targetUser = allUsers.find(u => (u.email || '').toLowerCase().trim() === userEmail.toLowerCase().trim());
            const currentKycData = targetUser?.profile?.kycData || {};

            const updatedData = {
                ...currentKycData,
                documentUrl: base64Url,
                frontImage: base64Url,
                documentType: file.name.endsWith('.pdf') ? 'PDF Verification Document' : 'Uploaded Government ID',
                submittedAt: new Date().toISOString(),
                auditHash: `SHA256-${Math.random().toString(36).substring(2, 10).toUpperCase()}-UPLOADED`
            };

            await db.updateUserKycData(userEmail, updatedData, 'pending');
            await fetchStats();
            addAdminToast('success', 'IDENTITY DOCUMENT UPLOADED', `Uploaded identity document for ${userEmail}. Status set to Pending Review.`);
            Haptics.success();
        };
        reader.readAsDataURL(file);
    };

    const getUserKycDetails = (user: UserRecord) => {
        const profile = user?.profile || {} as any;
        const email = user?.email || profile.email || 'entity@sovereign.bank';
        const name = profile.name || email.split('@')[0];
        const kycData = profile.kycData || {};

        const seedVal = Math.abs(email.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0));
        const passportNo = profile.governmentIdNumber || `P${10000000 + (seedVal * 314159) % 89999999}`;
        const docType = kycData.documentType || profile.governmentIdType || "International Passport / National ID";

        const frontImg = kycData.frontImage || kycData.documentUrl || profile.governmentIdBase64 || "https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=800&q=80";
        const backImg = kycData.backImage || "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=800&q=80";
        const selfieImg = kycData.selfieImage || kycData.selfieUrl || profile.profilePictureUrl || `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=0D8ABC&color=fff&size=256`;
        const addressImg = kycData.addressImage || "https://images.unsplash.com/photo-1554224155-8d04cb21cd6c?auto=format&fit=crop&w=800&q=80";

        const submittedDate = kycData.submittedAt ? new Date(kycData.submittedAt).toLocaleDateString([], { year: 'numeric', month: 'short', day: '2-digit' }) : new Date(Date.now() - (seedVal % 14 + 1) * 86400000).toLocaleDateString([], { year: 'numeric', month: 'short', day: '2-digit' });
        const auditHash = kycData.auditHash || `SHA256-${seedVal.toString(16).toUpperCase()}-NODE-${profile.kycStatus === 'verified' ? 'PASS' : 'REVIEW'}`;

        return {
            documentType: docType,
            documentNumber: passportNo,
            frontImage: frontImg,
            backImage: backImg,
            selfieImage: selfieImg,
            addressImage: addressImg,
            submittedAt: submittedDate,
            auditHash: auditHash,
            extractedData: kycData.extractedData || {
                fullName: name,
                documentNumber: passportNo,
                issuingCountry: profile.citizenship || "United States (USA)",
                nationality: "American",
                dateOfBirth: profile.dateOfBirth || "1988-04-12",
                expiryDate: profile.governmentIdExpiry || "2031-11-20",
                address: profile.addressStreet || profile.address || "100 Financial Plaza, Suite 400",
                mrzLine: `P<USA${name.toUpperCase().replace(/\s+/g, '<')}<<<<<<<<<<<<<<<<<<<<<`,
                sanctionCheck: "CLEAN (0 Hits)",
                pepCheck: "NON-PEP ENTITY",
                interpolFlag: "CLEAR"
            }
        };
    };

    const handleBulkKycUpdate = async (status: 'verified' | 'rejected' | 'pending' | 'unverified') => {
        if (!selectedUserIds.length) return;
        Haptics.heavy();
        setIsBulkActionProcessing(true);
        try {
            for (const email of selectedUserIds) {
                await db.updateUserKycStatus(email, status as any);
                await db.logAuditAction(userProfile.email, 'Bulk KYC Status Update', `Updated KYC status for ${email} to ${status}`);
            }
            await fetchStats();
            setSelectedUserIds([]);
            Haptics.success();
            socket.emit('admin:activity_stream', {
                type: 'Bulk Action',
                message: `Bulk KYC status updated to ${status.toUpperCase()} for ${selectedUserIds.length} entities.`,
                severity: status === 'verified' ? 'info' : 'warning'
            });
        } catch (e) {
            console.error('Bulk update failed', e);
            Haptics.warning();
        } finally {
            setIsBulkActionProcessing(false);
        }
    };

    const handleBatchTxStatusUpdate = async (newStatus: TransactionStatus) => {
        if (!selectedTxIds.length) return;
        Haptics.heavy();
        setIsBulkActionProcessing(true);
        try {
            for (const txId of selectedTxIds) {
                await db.updateTransactionStatus(txId, newStatus);
                await db.logAuditAction(userProfile.email, 'Batch Transaction Status Update', `Updated transaction ${txId} status to ${newStatus}`);
                const targetTx = allTransactions.find(t => t.id === txId);
                if (targetTx) {
                    socket.emit('admin:payment_status_changed', {
                        email: targetTx.accountId,
                        txId,
                        status: newStatus
                    });
                }
            }
            await fetchStats();
            socket.emit('admin:activity_stream', {
                type: 'Batch Transaction Action',
                message: `Bulk status update (${newStatus}) applied to ${selectedTxIds.length} transactions.`,
                severity: newStatus === TransactionStatus.COMPLETED ? 'info' : 'warning'
            });
            setSelectedTxIds([]);
            Haptics.success();
        } catch (e) {
            console.error('Batch transaction status update failed', e);
            Haptics.warning();
        } finally {
            setIsBulkActionProcessing(false);
        }
    };

    const handleBatchDeleteTransactions = async () => {
        if (!selectedTxIds.length) return;
        Haptics.warning();
        if (!confirm(`Are you sure you want to permanently delete ${selectedTxIds.length} selected transaction record(s)? This operation cannot be undone.`)) return;
        setIsBulkActionProcessing(true);
        try {
            await db.deleteTransactions(selectedTxIds);
            await db.logAuditAction(userProfile.email, 'Batch Delete Transactions', `Deleted ${selectedTxIds.length} transactions: ${selectedTxIds.join(', ')}`);
            await fetchStats();
            socket.emit('admin:activity_stream', {
                type: 'Batch Transaction Action',
                message: `Permanently deleted ${selectedTxIds.length} transaction entries from ledger.`,
                severity: 'warning'
            });
            setSelectedTxIds([]);
            Haptics.success();
        } catch (e) {
            console.error('Batch transaction deletion failed', e);
            Haptics.warning();
        } finally {
            setIsBulkActionProcessing(false);
        }
    };

