    const getStatusPrecedence = (status: TransactionStatus): number => {
        switch (status) {
            case TransactionStatus.COMPLETED:
            case TransactionStatus.FAILED:
                return 3;
            case TransactionStatus.FLAGGED_AWAITING_CLEARANCE:
            case TransactionStatus.PAUSED_ON_HOLD:
                return 2;
            case TransactionStatus.AWAITING_PAYMENT_VERIFICATION:
                return 1;
            default:
                return 0;
        }
    };

    useEffect(() => {
        if (initialTransactions && initialTransactions.length > 0) {
            setAllTransactions(prevTxs => {
                const txMap = new Map(prevTxs.map(t => [t.id, t]));
                initialTransactions.forEach(newTx => {
                    const prevTx = txMap.get(newTx.id);
                    if (prevTx) {
                        const prevLatest = Math.max(...Object.values(prevTx.statusTimestamps || {}).map(d => new Date(d as any).getTime()), 0);
                        const newLatest = Math.max(...Object.values(newTx.statusTimestamps || {}).map(d => new Date(d as any).getTime()), 0);
                        if (prevLatest > newLatest) {
                            return; // Keep previous if it has higher precedence
                        }
                    }
                    txMap.set(newTx.id, newTx);
                });
                return Array.from(txMap.values());
            });
        }
    }, [initialTransactions]);

    useEffect(() => {
        let isMounted = true;
        
        const loadOptions = async () => {
            try {
                const options = await db.getSystemOptions();
                if (isMounted) {
                    setSystemOptions(options);
                }
            } catch (err) {
                console.warn('[AdminDashboard] Failed to fetch system options:', err);
            }
        };
        loadOptions();
        
        let isFetching = false;
        let updateDebounceTimer: NodeJS.Timeout | null = null;

        const fetchRealTimeData = async (isManualForceSync: boolean = false) => {
            if (isFetching) return;
            isFetching = true;
            try {
                const [users, txs, logs] = await Promise.all([
                    db.getAllUsers(),
                    db.getAllTransactions(),
                    db.getAuditLogs()
                ]);
                
                if (isMounted) {
                    if (Array.isArray(users) && users.length > 0) {
                        setAllUsers(prevUsers => {
                            if (prevUsers.length === users.length) {
                                const isSame = prevUsers.every((u, i) => {
                                    const nu = users[i];
                                    return u.email === nu?.email &&
                                           u.profile?.name === nu?.profile?.name &&
                                           u.profile?.role === nu?.profile?.role &&
                                           u.profile?.kycStatus === nu?.profile?.kycStatus &&
                                           u.profile?.accountStatus === nu?.profile?.accountStatus &&
                                           u.profile?.isBanned === nu?.profile?.isBanned;
                                });
                                if (isSame) return prevUsers;
                            }
                            return users;
                        });
                    }
                    
                    if (isManualForceSync) {
                        setEntitiesLastSynced(new Date());
                    }

                    setSelectedUserDetails(prev => {
                        if (prev && prev.isOpen && Array.isArray(users)) {
                            const fresh = users.find(u => u.email === prev.user.email);
                            if (fresh) {
                                return { ...prev, user: { ...fresh, accounts: prev.user.accounts } };
                            }
                        }
                        return prev;
                    });
                    
                    if (txs && txs.length > 0) {
                        setAllTransactions(prevTxs => {
                            return txs.map(newTx => {
                                const prevTx = prevTxs.find(t => t.id === newTx.id);
                                if (prevTx) {
                                    const prevLatest = Math.max(...Object.values(prevTx.statusTimestamps || {}).map(d => new Date(d as any).getTime()), 0);
                                    const newLatest = Math.max(...Object.values(newTx.statusTimestamps || {}).map(d => new Date(d as any).getTime()), 0);
                                    if (prevLatest > newLatest) {
                                        return prevTx;
                                    }
                                }
                                return newTx;
                            });
                        });
                    }
                    setAuditLogs(logs || []);
                    setIsEntitiesLoading(false);
                }
            } catch (err) {
                console.error('[AdminDashboard] Critical failure in fetchRealTimeData:', err);
                if (isMounted) setIsEntitiesLoading(false);
            } finally {
                isFetching = false;
            }
        };

        const debouncedFetchRealTimeData = () => {
            if (updateDebounceTimer) clearTimeout(updateDebounceTimer);
            updateDebounceTimer = setTimeout(() => {
                fetchRealTimeData(false);
            }, 300);
        };

        const fetchWebhookLogs = async () => {
            try {
                const res = await fetch('/api/admin/webhook-events');
                if (res.ok && isMounted) {
                    const data = await res.json();
                    setWebhookLogs(data);
                }
            } catch (e) {
                console.warn('[AdminDashboard] Webhook fetch error:', e);
            }
        };

        fetchRealTimeDataRef.current = fetchRealTimeData;
        fetchRealTimeData();
        fetchWebhookLogs();

        const handleDbTransactionsUpdated = (e: Event) => {
            const detail = (e as CustomEvent).detail;
            if (Array.isArray(detail)) {
                setAllTransactions(prevTxs => {
                    return detail.map(newTx => {
                        const prevTx = prevTxs.find(t => t.id === newTx.id);
                        if (prevTx) {
                            const prevLatest = Math.max(...Object.values(prevTx.statusTimestamps || {}).map(d => new Date(d as any).getTime()), 0);
                            const newLatest = Math.max(...Object.values(newTx.statusTimestamps || {}).map(d => new Date(d as any).getTime()), 0);
                            if (prevLatest > newLatest) {
                                return prevTx;
                            }
                        }
                        return newTx;
                    });
                });
            } else {
                debouncedFetchRealTimeData();
            }
        };

        const handleDbUsersUpdated = (e?: any) => {
            debouncedFetchRealTimeData();
        };

        const handleDbAccountsUpdated = () => {
            debouncedFetchRealTimeData();
        };

        window.addEventListener('db_transactions_updated', handleDbTransactionsUpdated);
        window.addEventListener('db_users_updated', handleDbUsersUpdated);
        window.addEventListener('db_accounts_updated', handleDbAccountsUpdated);
        
        // Gentle periodic background check every 25 seconds for admin responsiveness without flickering
        const intervalId = setInterval(() => fetchRealTimeData(false), 25000);

        // Register admin socket
        socket.emit('register_user', { email: userProfile.email });

        // Connect Sync events
        socket.on('sync_interventions', (data: any[]) => {
            if (isMounted) {
                console.log('[Admin WS Sync] Sync Active Interventions:', data);
                setInterventions(data);
            }
});

        socket.on('admin:intervention_triggered', async (data: any) => {
            if (isMounted) {
                console.log('[Admin WS Alert] Received Intervention:', data);
                if (data && data.txId) addLedgerEntry('Security Alert', `Intervention triggered for TX: ${data.txId}`, 'warning');
                setInterventions(prev => {
                    const filtered = prev.filter(i => i.txId !== data.txId);
                    return [data, ...filtered];
});
                const updatedTxs = await db.getAllTransactions();
                setAllTransactions(updatedTxs);
            }
});

        socket.on('user:intervention_resolved', (data: any) => {
            if (isMounted) {
                setInterventions(prev => prev.filter(i => i.txId !== data.txId));
            }
});

        socket.on('system:maintenance_mode', (data: any) => {
            if (isMounted) {
                setIsMaintenanceMode(data.isEnabled);
            }
});

        socket.on('admin:system_options_updated', (data: any) => {
            if (isMounted && data) {
                setSystemOptions(data);
            }
        });

        socket.on('admin:users_updated', () => {
            if (isMounted) {
                fetchRealTimeData(true);
            }
        });

        // Add Ledger append listener
        const addLedgerEntry = (type: string, message: string, severity: 'info' | 'warning' | 'critical' = 'info') => {
            if (isMounted) {
                setActivityLedger(prev => [{ id: Math.random().toString(), timestamp: new Date(), type, message, severity }, ...prev].slice(0, 50));
            }
        };

        socket.on('admin:activity_stream', (data: any) => {
            addLedgerEntry(data.type, data.message, data.severity);
});

        socket.on('presence_update', (entries: any[]) => {
            if (isMounted) {
                const presenceMap: Record<string, any> = {};
                for (const [email, presence] of entries) {
                    presenceMap[email] = presence;
                }
                setRealPresence(presenceMap);
            }
});

        socket.on('admin:webhook_received', (newWebhook: any) => {
            if (isMounted) {
                console.log('[Admin WS Webhook] Real-time received:', newWebhook);
                addLedgerEntry('System Webhook', `Inbound Webhook Received: ${newWebhook.type}`, 'info');
                setWebhookLogs(prev => {
                    const filtered = prev.filter(w => w.id !== newWebhook.id);
                    return [newWebhook, ...filtered];
});
            }
});

        socket.on('admin:webhook_reconciled', (data: { webhookId: string; logEntry: any }) => {
            if (isMounted && data?.logEntry) {
                console.log('[Admin WS Webhook] Reconciled event received:', data);
                setWebhookLogs(prev => prev.map(w => w.id === data.webhookId ? data.logEntry : w));
            }
});

        // Fetch integration diagnostics once
        fetch('/api/config-status')
            .then(res => res.json())
            .then(data => {
                if (isMounted) setConfigStatus(data);
            })
            .catch(err => console.error('[Diagnostics Error]', err));

        return () => {
            isMounted = false;
            clearInterval(intervalId);
            window.removeEventListener('db_transactions_updated', handleDbTransactionsUpdated);
            window.removeEventListener('db_users_updated', handleDbUsersUpdated);
            window.removeEventListener('db_accounts_updated', handleDbAccountsUpdated);
            socket.off('sync_interventions');
            socket.off('admin:intervention_triggered');
            socket.off('user:intervention_resolved');
            socket.off('admin:system_options_updated');
            socket.off('admin:webhook_received');
            socket.off('admin:webhook_reconciled');
            socket.off('presence_update');
        };
    }, [userProfile.email]);

    useEffect(() => {
        const handleAccountsUpdateEvent = async (e: any) => {
            if (selectedUserDetails?.user?.email) {
                 try {
                     const accounts = await db.getAccounts(selectedUserDetails.user.email);
                     setSelectedUserDetails(prev => prev && prev.isOpen ? { ...prev, user: { ...prev.user, accounts } } : prev);
                     if (isEditingUser) {
                         setEditAccounts(accounts || []);
                     }
                 } catch (err) {
                     console.warn('Failed to sync accounts for selected user', err);
                 }
            }
        };
        window.addEventListener('db_accounts_updated', handleAccountsUpdateEvent);
        return () => window.removeEventListener('db_accounts_updated', handleAccountsUpdateEvent);
    }, [selectedUserDetails?.user?.email, isEditingUser]);

    const handleUpdateStatus = async (txId: string, status: TransactionStatus) => {
        await db.updateTransactionStatus(txId, status);
        await db.logAuditAction(userProfile.email, 'Update Transaction Status', `Updated transaction ${txId} to ${status}`);
        
        // Real-time socket emit for payment status updates
        const targetTx = allTransactions.find(t => t.id === txId);
        if (targetTx) {
            socket.emit('admin:payment_status_changed', {
                email: targetTx.accountId,
                txId,
                status,
                message: status === TransactionStatus.COMPLETED ? 'Sovereign Release Successful' : 'Compliance hold finalized'
});

            // Trigger Automatic immediate advice/instruction email to user
            const targetUser = allUsers.find(u => u.accounts?.some(a => a.id === targetTx.accountId));
            const trueEmail = targetUser ? targetUser.email : ((targetTx as any).senderEmail || targetTx.accountId);
                let statusColor = '#3b82f6';
                if (status === TransactionStatus.COMPLETED) {
                    statusColor = '#10b981';
                } else if (status === TransactionStatus.FAILED) {
                    statusColor = '#ef4444';
                } else if (status === TransactionStatus.PAUSED_ON_HOLD) {
                    statusColor = '#f59e0b';
                }

                const emailSubject = `Institutional Status Update: Transfer ${txId} is ${status}`;
                const titleText = `TRANSFER ${status.toUpperCase()}`;

                const formattedAmt = Number(targetTx.sendAmount || targetTx.receiveAmount || 0).toLocaleString('en-US', { minimumFractionDigits: 2 });
                const cur = targetTx.baseCurrency || targetTx.receiveCurrency || 'USD';

                const bodyHtml = generateBankingEmailTemplate(
                    titleText,
                    `<p style="font-size:15px;color:#cbd5e1;">Dear Sovereign Client,</p>
                     <p style="font-size:14px;color:#cbd5e1;">This is an official confirmation that your transaction <strong>${txId}</strong> has been updated to <strong style="color:${statusColor};">${status}</strong> by the clearing system administration.</p>
                     
                     <div style="background-color:#1e293b;border:1px solid #334155;padding:18px;border-radius:12px;margin:24px 0;">
                         <table style="width:100%;font-size:13px;color:#94a3b8;border-collapse:collapse;">
                             <tr>
                                 <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Transaction Ref:</td>
                                 <td style="padding:6px 0;text-align:right;font-family:monospace;">${txId}</td>
                             </tr>
                             <tr>
                                 <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Transfer Amount:</td>
                                 <td style="padding:6px 0;text-align:right;color:#ffffff;font-weight:bold;font-size:15px;">$${formattedAmt} ${cur}</td>
                             </tr>
                             ${targetTx.fee > 0 ? `<tr>
                                 <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Calculated Service Fee:</td>
                                 <td style="padding:6px 0;text-align:right;">$${Number(targetTx.fee).toLocaleString('en-US', { minimumFractionDigits: 2 })} ${cur}</td>
                             </tr>` : ''}
                             <tr>
                                 <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Description:</td>
                                 <td style="padding:6px 0;text-align:right;">${targetTx.description || 'Verified Interbank Pool'}</td>
                             </tr>
                             <tr>
                                 <td style="padding:6px 0;font-weight:bold;color:#cbd5e1;">Audit Status:</td>
                                 <td style="padding:6px 0;text-align:right;color:${statusColor};font-weight:bold;">${status}</td>
                             </tr>
                         </table>
                     </div>
                     
                     <p style="font-size:13px;color:#94a3b8;line-height:1.6;">
                         Our clearing system is designed for real-time asset transit and legal alignment. If you did not initiate this transaction or believe there has been an error, please lock your credential set immediately.
                     </p>
                     <p style="font-size:12px;color:#64748b;margin-top:24px;">First Pacific Banking Enclave, Operational Systems Support Node</p>`
                );

                sendEmail(
                    trueEmail,
                    emailSubject,
                    bodyHtml
                );
        }

        const updated = await db.getAllTransactions();
        setAllTransactions(updated);
        const logs = await db.getAuditLogs();
        setAuditLogs(logs);
    };

    const handleIssueComplianceHaltCode = async (txId: string) => {
        const targetTx = allTransactions.find(t => t.id === txId);
        if (!targetTx) return;

        const codeDigits = Math.floor(100000 + Math.random() * 900000);
        const code = `HALT-${codeDigits}`;

        targetTx.regulatoryAuthCode = code;
        targetTx.status = TransactionStatus.FLAGGED_AWAITING_CLEARANCE;
        
        await db.saveTransaction(targetTx);
        await db.logAuditAction(userProfile.email, 'Issue Compliance Halt Code', `Generated code ${code} for transaction ${txId}`);

        socket.emit('admin:resolve_intervention', {
            txId: txId,
            resolution: 'approved',
            type: 'FUNDS CLEARANCE',
            code: code
});

        // Trigger Automatic advice/instruction email to user
        const targetUser = allUsers.find(u => u.accounts?.some(a => a.id === targetTx.accountId));
        const trueEmail = targetUser ? targetUser.email : ((targetTx as any).senderEmail || targetTx.accountId);
            sendEmail(
                trueEmail,
                "IMMEDIATE ACTION REQUIRED: Settlement Clearance Code Appended",
                generateBankingEmailTemplate(
                    'SECURITY CLEARANCE CODE UNLOCKED',
                    `<p style="font-size:14px;color:#cbd5e1;">We have successfully received and verified your settlement receipt file for transfer reference <strong>${txId}</strong> of <strong>${formatCurrency(targetTx.sendAmount)}</strong>.</p>
                     
                     <div style="background-color:#1e293b;border:1px solid #e2e8f0;border-left:4px solid #f59e0b;padding:16px;border-radius:12px;margin:24px 0;text-align:center;">
                         <p style="font-[monospace];font-weight:900;font-size:24px;letter-spacing:4px;color:#f59e0b;margin:0 0 8px 0;">${code}</p>
                         <p style="font-[sans-serif];font-weight:700;font-size:11px;letter-spacing:1px;color:#94a3b8;margin:0;text-transform:uppercase;">OFFICIAL UNLOCK ACCESS CODE</p>
                     </div>

                     <p style="font-size:13px;color:#94a3b8;line-height:1.6;">
                         <strong>Entry Instructions:</strong><br/>
                         1. Navigate to your Account Dashboard's <strong>Recent Activity</strong> log.<br/>
                         2. Click on the pending international transfer <strong>${txId}</strong> to launch the Details Core console.<br/>
                         3. Insert the official clearance code <strong>${code}</strong> exactly into the dedicated <em>Compliance Halt Code</em> validation input.<br/>
                         4. Click <strong>Unlock & Finalize</strong>. The interbank transfer engine will immediately resume instruction execution.
                     </p>
                     
                     <p style="font-size:12px;color:#64748b;margin-top:24px;">First Pacific Banking Enclave, Operational Systems Support Node</p>`
                )
                );

        const updated = await db.getAllTransactions();
        setAllTransactions(updated);
        const logsChange = await db.getAuditLogs();
        setAuditLogs(logsChange);

        addAdminToast('info', 'System Notification', `Successfully generated Compliance Halt Code: ${code} and dispatched instruction email!`);
    };


