    const handleToggleUserPaymentMethod = async (user: UserRecord, method: string) => {
        const currentDisabled = user.profile.disabledPaymentMethods || [];
        const newDisabled = currentDisabled.includes(method)
            ? currentDisabled.filter(m => m !== method) // Remove to enable
            : [...currentDisabled, method];             // Add to disable

        // Instantly update local React state for real-time visual responsiveness
        setAllUsers(prev => prev.map(u => u.email === user.email ? {
            ...u,
            profile: { ...u.profile, disabledPaymentMethods: newDisabled }
        } : u));
        if (selectedUserDetails && selectedUserDetails.user.email === user.email) {
            setSelectedUserDetails(prev => prev ? {
                ...prev,
                user: {
                    ...prev.user,
                    profile: { ...prev.user.profile, disabledPaymentMethods: newDisabled }
                }
            } : null);
        }

        await db.updateUserProfile(user.email, { disabledPaymentMethods: newDisabled });
        await db.logAuditAction(userProfile.email, 'Protocol Selection Payment Flow Override', `${currentDisabled.includes(method) ? 'Enabled' : 'Disabled'} ${method.toUpperCase()} protocol flow for ${user.email}`);

        const updated = await db.getAllUsers();
        setAllUsers(updated);

        const freshUser = updated.find(u => u.email === user.email);
        if (freshUser && selectedUserDetails) {
            setSelectedUserDetails(prev => prev ? { ...prev, user: freshUser } : null);
        }
    };

