            doc.text("Executive AML Metrics & Transaction Volume Report", 14, 20);
            
            doc.setFontSize(10);
            doc.setFont("helvetica", "normal");
            doc.text(`Generated on: ${new Date().toLocaleString()}`, 14, 28);
            doc.text(`Administrator: ${userProfile.email}`, 14, 34);

            doc.setDrawColor(200);
            doc.line(14, 38, 196, 38);

            const totalVolume = allTransactions.reduce((acc, tx) => acc + (tx.sendAmount || 0), 0);
            const highRiskCount = allTransactions.filter(tx => (tx.sendAmount || 0) > 50000).length;
            const flaggedUsers = allUsers.filter(u => u.profile.kycStatus === 'rejected' || u.profile.kycStatus === 'pending').length;

            doc.setFontSize(14);
            doc.setFont("helvetica", "bold");
            doc.text("Key Metrics", 14, 50);
            
            doc.setFontSize(12);
            doc.setFont("helvetica", "normal");
