    const handleDownloadReceipt = async (transaction: Transaction) => {
        let sourceAccount = globalAccounts.find(a => a.id === transaction.accountId);
        if (!sourceAccount) {
            const userAccounts = await db.getAccounts(transaction.accountId) || [];
            sourceAccount = userAccounts[0] || {
                id: transaction.accountId,
                userId: 'unknown',
                nickname: 'Premium Business Checking',
                balance: 1000000,
                accountNumber: '••••' + transaction.accountId.slice(-4),
                fullAccountNumber: '00000000' + transaction.accountId.slice(-4),
                routingNumber: '021000021'
            } as any;
        }
        setIsGeneratingPdf(true);
        setPdfData({ transaction, account: sourceAccount });
        
        setTimeout(() => {
            const receiptElement = document.getElementById(`receipt-for-pdf-${transaction.id}`);
            if (receiptElement) {
                html2canvas(receiptElement, { scale: 3, backgroundColor: '#ffffff', useCORS: true }).then((canvas) => {
                    const imgData = canvas.toDataURL('image/png');
                    const pdf = new jsPDF({ orientation: 'portrait', unit: 'px', format: [canvas.width / 3, canvas.height / 3] });
                    pdf.addImage(imgData, 'PNG', 0, 0, canvas.width / 3, canvas.height / 3);
                    pdf.save(`FPB_Receipt_${transaction.id}.pdf`);
                    setIsGeneratingPdf(false);
                    setPdfData(null);
                }).catch((error) => {
                    console.error("PDF generation failed:", error);
                    setIsGeneratingPdf(false);
                    setPdfData(null);
});
            } else {
                setIsGeneratingPdf(false);
                setPdfData(null);
            }
        }, 600);
    };

    const confirmAdjustBalance = async () => {
        if (!adjustBalanceModal) return;
        const newBalance = parseFloat(adjustBalanceModal.newBalance);
        if (!isNaN(newBalance)) {
            const difference = newBalance - adjustBalanceModal.currentBalance;
            const txId = `tx_${Math.random().toString(36).substring(2, 10)}${Date.now()}`;
            
            const dummyTransaction: Transaction = {
                id: txId,
                accountId: adjustBalanceModal.accountId,
                recipient: {
                    id: 'ext_admin_' + Math.random().toString(36).substring(2, 6),
                    fullName: adjustBalanceModal.source || 'Sovereign Core Balance Alignment',
                    bankName: adjustBalanceModal.source || 'Sovereign Core Balance Alignment',
                    accountNumber: '****' + Math.floor(Math.random() * 9000 + 1000).toString(),
                    country: { code: 'US', name: 'United States', currency: 'USD', symbol: '$' },
                    realDetails: {
                        accountNumber: '••••' + Math.floor(Math.random() * 9000 + 1000).toString(),
                        swiftBic: 'FPB' + Math.floor(Math.random() * 900000 + 100000).toString()
                    }
                },
                sendAmount: Math.abs(difference),
                receiveAmount: Math.abs(difference),
                fee: 0,
                exchangeRate: 1.0,
                status: difference > 0 ? TransactionStatus.FUNDS_ARRIVED : TransactionStatus.COMPLETED,
                estimatedArrival: new Date(),
                statusTimestamps: {
                    [TransactionStatus.SUBMITTED]: new Date(),
                    [TransactionStatus.COMPLETED]: new Date()
                },
                description: `${difference > 0 ? 'Credited from' : 'Debited to'} ${adjustBalanceModal.source || 'Sovereign Core Balance Alignment'}`,
                type: difference > 0 ? 'credit' : 'debit',
                isAdjustment: true,
                federallyVerified: true,
                adjustmentSourceBank: adjustBalanceModal.source || 'Sovereign Core Balance Alignment',
                adjustmentAdminEmail: userProfile.email
            };

            if (difference > 0) {
                // Perform atomic credit, audit logging, and email dispatch
                await db.atomicCreditAndNotify(
                    adjustBalanceModal.userEmail,
                    adjustBalanceModal.accountId,
                    difference,
                    dummyTransaction,
                    userProfile.email,
                    'Credit Issuance (Direct Balance Adjustment)',
                    `Adjusted/credited balance for ${adjustBalanceModal.userEmail} to ${newBalance} (Diff: +$${difference} USD) via ${adjustBalanceModal.source || 'Sovereign Core Balance Alignment'}.`
                );

                // Forced Push Socket Emission to ensure zero-latency UI reflection for connected clients
                socket.emit('admin:force_accounts_update', {
                    email: adjustBalanceModal.userEmail,
                    accountId: adjustBalanceModal.accountId,
                    newBalance: newBalance
                });
            } else {
                await db.updateAccountBalance(adjustBalanceModal.userEmail, adjustBalanceModal.accountId, newBalance);
                await db.logAuditAction(userProfile.email, 'Adjust Balance', `Adjusted balance for ${adjustBalanceModal.userEmail} to ${newBalance} (Diff: ${difference}) via ${adjustBalanceModal.source}`);
            }
            
            socket.emit('admin:compliance_alert', { 
                action: 'Direct Balance Adjustment', 
                message: `Admin ${userProfile.email} adjusted balance for ${adjustBalanceModal.userEmail} to ${newBalance}.`,
                severity: 'critical'
});

            // Emit real-world ledger alignment to socket
            socket.emit('admin:adjust_balance', {
                email: adjustBalanceModal.userEmail,
                accountId: adjustBalanceModal.accountId,
                currentBalance: adjustBalanceModal.currentBalance,
                newBalance: newBalance,
                reason: adjustBalanceModal.source || 'Sovereign Core Balance Alignment'
});

            // If there's a difference and source is specified, log a real transaction
            if (difference !== 0 && adjustBalanceModal.source) {
                await db.saveTransaction(dummyTransaction);
                setAllTransactions(prev => [dummyTransaction, ...prev]);

                if (adjustBalanceModal.notifyUser) {
                    try {
                        const targetUser = allUsers.find(u => u.email === adjustBalanceModal.userEmail);
                        if (targetUser && difference > 0) {
                            await fetch('/api/admin/broadcast-message', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/json' },
                                body: JSON.stringify({
                                    emails: [adjustBalanceModal.userEmail],
                                    channel: 'email',
                                    subject: 'Incoming Wire Transfer Alert',
                                    body: `Dear ${targetUser.profile.name},\n\nA new deposit of ${formatCurrency(Math.abs(difference))} has cleared into your account ending in ${adjustBalanceModal.accountId.slice(-4)}.\n\nOrigin Details:\n${adjustBalanceModal.source}\nRef: ${txId}\n\nYour new available balance is ${formatCurrency(newBalance)}.`
                                })
});
                        }
                    } catch (e) {
                        console.warn('Failed to send adjustment email alert', e);
                    }
                }
            }

            const logs = await db.getAuditLogs();
            setAuditLogs(logs);
            setAdjustBalanceModal(null);
        }
    };

