    const handleExecuteSupremeCommand = async () => {
        if (!execSelectedUser) return;
        Haptics.heavy();
        setExecIsProcessing(true);
        try {
            const userEmail = execSelectedUser.email;
            
            // 1. Process balance adjustments if specified
            const amtParsed = parseFloat(execInjectionAmount);
            if (!isNaN(amtParsed) && amtParsed > 0 && execSelectedAccountId) {
                const targetAct = ((execSelectedUser.accounts || []) as any[]).find((a: any) => a.id === execSelectedAccountId) || 
                                  (await db.getAccounts(userEmail)).find((a: any) => a.id === execSelectedAccountId);
                if (targetAct) {
                    const balanceDiff = execInjectionType === 'credit' ? amtParsed : -amtParsed;
                    
                    const txId = 'EXEC-' + Math.random().toString(36).substring(2, 10).toUpperCase();
                    const newTx = {
                        id: txId,
                        accountId: execSelectedAccountId,
                        recipient: {
                            id: 'exec-rec',
                            fullName: execSelectedUser.profile.name,
                            bankName: 'Sovereign Treasury',
                            accountNumber: targetAct.accountNumber,
                            country: { code: 'US', name: 'United States', currency: 'USD', symbol: '$' }
                        },
                        sendAmount: amtParsed,
                        receiveAmount: amtParsed,
                        fee: 0,
                        exchangeRate: 1,
                        type: execInjectionType,
                        description: execReferenceLabel || 'Supreme Executive Override',
                        status: 'COMPLETED',
                        estimatedArrival: new Date(),
                        statusTimestamps: {
                            'SUBMITTED': new Date(),
                            'COMPLETED': new Date()
                        },
                        senderName: 'Sovereign Treasury',
                        senderEmail: 'treasury@firstpaba.com'
                    };

                    let finalBalance = 0;
                    if (execInjectionType === 'credit') {
                        // Atomic transaction with audit logging and awaiting/sending Resend email notification
                        finalBalance = await db.atomicCreditAndNotify(
                            userEmail,
                            execSelectedAccountId,
                            amtParsed,
                            newTx as any,
                            userProfile.email,
                            'Credit Issuance (Supreme Command)',
                            `Force injected balance credit of $${amtParsed} USD for user ${userEmail} (Account: ${targetAct.accountNumber}). Description: ${execReferenceLabel}.`
                        );

                        // Forced Push Socket Emission to ensure zero-latency UI reflection for connected clients
                        socket.emit('admin:force_accounts_update', {
                            email: userEmail,
                            accountId: execSelectedAccountId,
                            newBalance: finalBalance
                        });
                    } else {
                        finalBalance = Math.max(0, targetAct.balance + balanceDiff);
                        await db.updateAccountBalance(userEmail, execSelectedAccountId, finalBalance);
                        await db.logAuditAction(
                            userProfile.email,
                            'Executive Balance Overwrite',
                            `Force injected/adjusted balance for user ${userEmail} (Account: ${targetAct.accountNumber}) by -$${amtParsed}. Description: ${execReferenceLabel}. Final balance reconciled to $${finalBalance}.`
                        );
                    }
                    
                    socket.emit('admin:compliance_alert', { 
                        action: 'Supreme Command Balance Injection', 
                        message: `Admin ${userProfile.email} executed supreme balance change on ${userEmail}: added ${balanceDiff}.`,
                        severity: 'critical'
                    });

                    // Re-align real world socket
                    socket.emit('admin:adjust_balance', {
                        email: userEmail,
                        accountId: execSelectedAccountId,
                        currentBalance: targetAct.balance,
                        newBalance: finalBalance,
                        reason: `Supreme Admin Intervention: ${execReferenceLabel}`
                    });

                    await db.saveTransaction(newTx as any);

                    // Emit real-time transaction created event to trigger live email and instant UI sync
                    socket.emit('admin:manual_transaction_created', {
                        email: userEmail,
                        transaction: newTx,
                        newBalance: finalBalance,
                        accountId: execSelectedAccountId,
                        justification: execReferenceLabel || 'Supreme Executive Override'
                    });
                }
            }

            // 2. Adjust role privileges
            if (execRole !== execSelectedUser.profile.role) {
                await db.updateUserRole(userEmail, execRole);
                await db.logAuditAction(userProfile.email, 'Executive Privilege Level Escalation', `Escalated/De-escalated ${userEmail} to role tier "${execRole}"`);
            }

            // 3. Adjust KYC
            if (execKyc !== execSelectedUser.profile.kycStatus) {
                await db.updateUserKycStatus(userEmail, execKyc);
                await db.logAuditAction(userProfile.email, 'Executive KYC Override', `Modified user ${userEmail} KYC status to "${execKyc}"`);
            }

            // 4. Overwrite ban status & suspended status & requireAdminApproval status
            if (execIsBanned !== execSelectedUser.profile.isBanned) {
                await db.updateUserBannedStatus(userEmail, execIsBanned);
                await db.logAuditAction(userProfile.email, 'Executive Ban Directive', `${execIsBanned ? 'Banned/Locked' : 'Unbanned/Released'} user ${userEmail}`);
            }

            if (execIsSuspended !== execSelectedUser.profile.isSuspended) {
                await db.updateUserSuspendedStatus(userEmail, execIsSuspended);
                await db.logAuditAction(userProfile.email, 'Executive Ledger Hold', `${execIsSuspended ? 'Suspended/Blocked transfers of' : 'Resumed/Authorized transfers of'} user ${userEmail}`);
            }

            if (execRequireApproval !== execSelectedUser.profile.requireAdminApprovalForPayments) {
                await db.updateUserRequireAdminApproval(userEmail, execRequireApproval);
                await db.logAuditAction(userProfile.email, 'Executive Approval Requirement Override', `Forced payment approval precheck ${execRequireApproval ? 'ON' : 'OFF'} for ${userEmail}`);
            }

            // Re-fetch all users to sync UI
            const updated = await db.getAllUsers();
            setAllUsers(updated);
            const logs = await db.getAuditLogs();
            setAuditLogs(logs);

            // Close Drawer
            setExecDrawerOpen(false);
            setExecSelectedUser(null);
            Haptics.success();
        } catch (err) {
            console.error("Failed to run supreme executive command:", err);
            Haptics.warning();
        } finally {
            setExecIsProcessing(false);
        }
    };

    const handleResolveIntervention = (txId: string, email: string, resolution: 'approved' | 'rejected') => {
        socket.emit('admin:resolve_intervention', {
            txId,
            email,
            resolution,
            message: resolution === 'approved' ? 'Transaction security bypass permitted by clearing administrator.' : 'Transaction declined on regulatory investigation.'
});
        
        // Remove locally immediately
        setInterventions(prev => prev.filter(i => i.txId !== txId));
        
        // Push an audit log
        db.logAuditAction(userProfile.email, 'Security Override', `Overrode and ${resolution} transaction ${txId} for user ${email}`);
    };

    const handlePermanentDeleteUser = async (user: UserRecord) => {
        Haptics.warning();
        const confirmStr = window.prompt(`CRITICAL WARNING: You are about to permanently delete the account for ${user.email}. This cannot be undone.\n\nType 'DELETE' to confirm.`);
        if (confirmStr !== 'DELETE') return;
        
        try {
            const res = await db.deleteUserAccountPermanently(user.email, 'admin_delete_override');
            if (res.success) {
                addAdminToast('info', 'System Notification', `Account ${user.email} permanently deleted.`);
                db.logAuditAction(userProfile.email, 'SuperAdmin Delete User', `Permanently deleted user ${user.email}`);
                const updatedUsers = await db.getAllUsers();
                setAllUsers(updatedUsers);
                if (selectedUserDetails && selectedUserDetails.user.email === user.email) {
                    setSelectedUserDetails(null);
                }
                Haptics.success();
            } else {
                addAdminToast('error', 'System Alert', `Deletion failed: ${res.error}`);
                Haptics.warning();
            }
        } catch (err: any) {
            console.error('Delete error:', err);
            addAdminToast('error', 'System Alert', `Delete failed: ${err.message}`);
            Haptics.warning();
        }
    };

