    const handleSaveInlineRowChanges = async (oldEmail: string) => {
        try {
            const newEmailStr = rowEditEmail.trim().toLowerCase();
            if (!newEmailStr) {
                addAdminToast('info', 'System Notification', "Email address cannot be empty.");
                return;
            }

            // 1. Update general profile fields and email (supporting auth overrides in DB)
            await db.updateUserEmailAndProfile(oldEmail, newEmailStr, {
                name: rowEditName,
                phone: rowEditPhone,
                kycStatus: rowEditKyc,
                role: rowEditRole,
                isBanned: rowEditBanned,
                isSuspended: rowEditSuspended,
                requireAdminApprovalForPayments: rowEditRequireApproval,
                position: rowEditPosition,
                dateOfBirth: rowEditDob,
                sex: rowEditSex,
                address: rowEditAddress,
                profilePictureUrl: rowEditProfilePictureUrl
            }, rowEditPassword, rowEditPin);

            // Update safety controls individually
            await db.updateUserBannedStatus(newEmailStr, rowEditBanned);
            if (rowEditBanned) {
                socket.emit('admin:ban_user', { email: newEmailStr });
            } else {
                socket.emit('admin:unban_user', { email: newEmailStr });
            }

            await db.updateUserSuspendedStatus(newEmailStr, rowEditSuspended);
            if (rowEditSuspended) {
                socket.emit('admin:suspend_user', { email: newEmailStr });
            } else {
                socket.emit('admin:unsuspend_user', { email: newEmailStr });
            }

            await db.updateUserRequireAdminApproval(newEmailStr, rowEditRequireApproval);

            // 2. Commit all staged ledger accounts (checking, savings, investment balances)
            for (const account of rowEditAccounts) {
                await db.saveUserAccount(newEmailStr, account);
                await db.updateAccountBalance(newEmailStr, account.id, account.balance);
            }

            socket.emit('admin:compliance_alert', { 
                action: 'Grid Balance Alteration', 
                message: `Admin ${userProfile.email} adjusted inline grid profile/balances for ${newEmailStr}.`,
                severity: 'critical'
});

            // 3. Log comprehensive supervisor audit trail
            await db.logAuditAction(
                userProfile.email,
                'Inline Grid Profile Alteration',
                `Inline spreadsheet-grid super-edit committed for entity ${oldEmail} -> ${newEmailStr}. Role: ${rowEditRole}, KYC: ${rowEditKyc}, Balances aligned. Compliance Alert Triggered.`
            );

            // 4. Force state synchronizations
            setEditingUserEmail(null);
            const updatedUsers = await db.getAllUsers();
            setAllUsers(updatedUsers);
            await fetchStats();
            
            // Emit socket updates to trigger broad refresh for listeners
            socket.emit('admin:system_options_updated', {});
            
            addAdminToast('info', 'System Notification', "Sovereign profile alterations compiled and synchronized inline successfully in real time!");
        } catch (err: any) {
            console.error(err);
            addAdminToast('error', 'System Alert', `Sovereign core update failure: ${err.message || 'Unknown protocol violation'}`);
        }
    };

    const handleOnboardUser = async (e: React.FormEvent) => {
        e.preventDefault();
        setOnboardError(null);
        setOnboardSuccess(null);
        
        if (!onboardEmail || !onboardFirstName || !onboardLastName || !onboardPassword || !onboardPin) {
            setOnboardError('Please fill in all required fields (Email, First Name, Last Name, Password, PIN).');
            return;
        }

        setIsOnboardProcessing(true);
        try {
            const fullName = `${onboardFirstName} ${onboardLastName}`.trim();
            const bankSpecificId = `ID-${Math.floor(10000000 + Math.random() * 90000000)}`;
            const profile: UserProfile = {
                name: fullName,
                email: onboardEmail,
                phone: onboardPhone || '',
                profilePictureUrl: onboardProfilePic || '',
                bankIdNumber: bankSpecificId,
                role: 'user',
                kycStatus: 'verified', // Auto verify since admin is onboarding
                kycData: {
                    documentUrl: onboardIdDoc || '',
                    selfieUrl: onboardProfilePic || '',
                    submittedAt: new Date(),
                },
                lastLogin: {
                    date: new Date(),
                    from: 'System Portal (Admin)'
                }
            };

            const result = await db.createUser(profile, onboardPassword, onboardPin, true);
            
            if (result !== 'VERIFICATION_REQUIRED') {
                const initBalance = parseFloat(onboardBalance) || 0;
                
                // Set the initial balance for the default account
                const accounts = await db.getAccounts(onboardEmail);
                if (accounts && accounts.length > 0) {
                    const firstAccount = accounts[0];
                    firstAccount.balance = initBalance;
                    firstAccount.type = onboardAccountType === 'checking' 
                        ? AccountType.CHECKING 
                        : onboardAccountType === 'savings' 
                            ? AccountType.SAVINGS 
                            : AccountType.BUSINESS;
                    await db.saveUserAccount(onboardEmail, firstAccount);
                }

                // Fetch fully resolved accounts to include all detailed fields
                const finalAccounts = await db.getAccounts(onboardEmail);
                const currentBrandOpts = systemOptions || await db.getSystemOptions().catch(() => (null));

                // Generate PDF Credentials Document
                let pdfBase64 = '';
                try {
                    const doc = new jsPDF();
                    doc.setFontSize(22);
                    doc.text('Welcome Kit Credentials', 20, 20);
                    doc.setFontSize(14);
                    doc.text(`Bank Name: ${currentBrandOpts?.customIssuer || 'First Pacific Bank'}`, 20, 30);
                    doc.text(`Customer Name: ${fullName}`, 20, 40);
                    doc.text(`Email Address: ${onboardEmail}`, 20, 50);
                    doc.text(`Bank Specific ID: ${bankSpecificId}`, 20, 60);
                    doc.text(`SSN/ITIN: ***-**-${onboardSsn.slice(-4)}`, 20, 70);
                    
                    let yOffset = 90;
                    doc.setFontSize(16);
                    doc.text('Account Details', 20, 80);
                    doc.setFontSize(12);
                    finalAccounts.forEach((acct, index) => {
                        doc.text(`Account Type: ${acct.type}`, 20, yOffset);
                        doc.text(`Account Number: ${acct.fullAccountNumber || acct.accountNumber}`, 20, yOffset + 10);
                        doc.text(`Routing Number: ${acct.routingNumber || '122000218'}`, 20, yOffset + 20);
                        doc.text(`Available Balance: $${(acct.balance || 0).toLocaleString('en-US', { minimumFractionDigits: 2 })}`, 20, yOffset + 30);
                        yOffset += 50;
                    });
                    
                    doc.setFontSize(16);
                    doc.text('Secure Credentials', 20, yOffset);
                    doc.setFontSize(12);
                    doc.text(`Temporary Password: ${onboardPassword}`, 20, yOffset + 10);
                    doc.text(`Secure PIN: ${onboardPin}`, 20, yOffset + 20);
                    
                    const pdfDataStr = doc.output('datauristring');
                    // Extract base64
                    pdfBase64 = pdfDataStr.split(',')[1] || '';
                } catch (pdfErr) {
                    console.error('[ONBOARDING_PDF] Failed to generate PDF credentials', pdfErr);
                }

                // Dispatch real fully functional onboarding congratulations email
                try {
                    await sendOnboardingEmail(
                        { name: fullName, email: onboardEmail, ssn: onboardSsn, bankIdNumber: bankSpecificId },
                        finalAccounts || [],
                        onboardPassword,
                        onboardPin,
                        initBalance,
                        currentBrandOpts,
                        pdfBase64
                    );
                    console.log('[ONBOARDING_EMAIL] Successfully sent credentials and banking details to:', onboardEmail);
                } catch (emailErr) {
                    console.error('[ONBOARDING_EMAIL] Failed to send congratulations email:', emailErr);
                }

                await db.logAuditAction(userProfile.email, 'SuperAdmin Live Onboarding', `Instant verification & onboarding completed for new entity ${onboardEmail}. Initial allocation: ${initBalance}`);
                
                const updatedUsers = await db.getAllUsers();
                setAllUsers(updatedUsers);
                
                setIsOnboardingUser(false);
                setOnboardEmail('');
                setOnboardFirstName('');
                setOnboardLastName('');
                setOnboardSsn('');
                setOnboardProfilePic('');
                setOnboardIdDoc('');
                setOnboardPassword('');
                setOnboardPin('');
                setOnboardPhone('');
                setOnboardBalance('0');
                
                setOnboardSuccess(`Real-Time Onboarding Successful for ${onboardEmail}. Identity Verified, Ledgers Initiated.`);
                setTimeout(() => {
                    setIsOnboardingUser(false);
                    setOnboardSuccess(null);
                }, 3000);
            } else {
                setOnboardError('Verification required unexpectedly.');
            }
        } catch (error: any) {
            setOnboardError(error.message || 'Failed to onboard new user.');
        } finally {
            setIsOnboardProcessing(false);
        }
    };

